preset.warp:
uniform sampler2D sampler_cover;
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's average colour: its smallest mipmap level.
vec3 coverAverage() {
  return textureLod(sampler_cover, vec2(0.5), 10.0).rgb;
}
mat2 turn(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, s, -s, c);
}
float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
    mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x), f.y),
    f.z);
}
float fbm(vec3 p, int octaves) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    sum += amp * noise3(p);
    p = p * 2.03 + 17.1;
    amp *= 0.5;
  }
  return sum;
}
float roundBox(vec3 p, vec3 b, float r) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r;
}
// The cover as a slab: q1 its swing, q2 its tilt, q8 the lift of the last
// beat.
vec3 slabSpace(vec3 p) {
  p.y -= 0.05 + 0.06 * q8;
  p.xz = turn(q1) * p.xz;
  p.yz = turn(q2) * p.yz;
  return p;
}
float slab(vec3 p) {
  return roundBox(slabSpace(p), vec3(0.96, 0.96, 0.035), 0.04);
}
vec3 slabNormal(vec3 p) {
  vec2 e = vec2(0.0015, 0.0);
  return normalize(vec3(
    slab(p + e.xyy) - slab(p - e.xyy),
    slab(p + e.yxy) - slab(p - e.yxy),
    slab(p + e.yyx) - slab(p - e.yyx)));
}
// One pixel's width per unit of distance along a ray: rays leave the eye
// through a screen 1.75 units away whose height is 1.
float pixelAngle() {
  return 1.0 / (texsize.y * 1.75);
}
// The moon, up to the right of the cover and behind it, so its light
// rims the cover and lays a glittering path across the sea to the viewer.
const vec3 MOON = vec3(0.2231, 0.0970, -0.9700);
const float MOON_SIZE = 0.02;
const vec3 MOONLIGHT = vec3(0.75, 0.82, 1.0);
float camAngle() {
  return 0.55 * sin(q7);
}
// Everything far away - sky, moon, clouds, stars and the lighthouse -
// turns together with this share of the camera's swing rather than all
// of it, so the moon and the lighthouse stay in the picture and keep
// their places against each other.
const float FAR_SWING = 0.22;
vec3 backdrop(vec3 d) {
  float a = (FAR_SWING - 1.0) * camAngle();
  float c = cos(a), s = sin(a);
  return vec3(d.x * c + d.z * s, d.y, -d.x * s + d.z * c);
}
// The Moon's near side, longitude -90 to 90 across and latitude 90 to -90
// down (see assets/milkdrop/pictures/).
uniform sampler2D sampler_moon;
// How bright the full moon is at p on the unit sphere (x east, y north,
// z towards the viewer). The mipmap level by hand, as this runs inside a
// branch: the map's texels per pixel, more towards the edge where the
// surface turns away.
vec3 moonFace(vec3 p) {
  vec2 latLon = vec2(asin(clamp(p.y, -1.0, 1.0)), atan(p.x, p.z));
  vec2 at = vec2(0.5 + latLon.y / 3.14159, 0.5 - latLon.x / 3.14159);
  float texels = 512.0 / 3.14159 * pixelAngle() / MOON_SIZE / max(p.z, 0.15);
  vec3 map = textureLod(sampler_moon, at, log2(max(texels, 1.0))).rgb;
  // The map is the surface's own brightness; a touch more contrast, as the
  // eye sees the full moon against the night.
  float l = dot(map, vec3(0.3, 0.52, 0.18));
  return mix(vec3(l), map, 0.5) * (0.55 + 0.75 * smoothstep(0.25, 0.75, l));
}
// Thin clouds on a layer high over the sea, drifting with the music, lit
// silver where they pass the moon. How much of the sky behind they hide,
// and their own light.
vec4 clouds(vec3 rd) {
  if (rd.y < 0.02) return vec4(0.0);
  vec2 at = rd.xz / rd.y * 0.6 + vec2(q10 * 0.8, q10 * 0.25);
  float c = fbm(vec3(at * 1.3, 4.0), 5);
  float wisps = fbm(vec3(at * 5.0 + c * 2.0, 9.0), 3);
  float cover = smoothstep(0.5, 0.8, c + (wisps - 0.5) * 0.25) * smoothstep(0.02, 0.15, rd.y);
  float nearMoon = max(dot(rd, MOON), 0.0);
  vec3 lit = MOONLIGHT * (0.012 + 0.25 * pow(nearMoon, 60.0) + 0.04 * pow(nearMoon, 6.0));
  return vec4(lit * cover, cover * 0.85);
}
// Night sky: deep blue overhead, paler towards the horizon, the accent in
// a glow along it where it meets the sea; the moon with its halo, and the
// clouds over all of it.
vec3 sky(vec3 rd) {
  rd = backdrop(rd);
  float up = max(rd.y, 0.0);
  vec3 col = mix(vec3(0.02, 0.028, 0.045), vec3(0.003, 0.006, 0.016), smoothstep(0.0, 0.5, up));
  col += accent() * 0.045 * exp(-abs(rd.y) * 12.0);
  float m = dot(rd, MOON);
  float a = acos(clamp(m, -1.0, 1.0));
  // Its halo, wide and faint in the air, close and bright around the disc.
  col += MOONLIGHT * (0.05 * exp(-a * 5.0) + 0.25 * exp(-a * 40.0)) * step(0.0, rd.y);
  if (a < MOON_SIZE * 1.2) {
    vec3 e1 = normalize(cross(MOON, vec3(0.0, 1.0, 0.0)));
    vec3 e2 = cross(e1, MOON);
    vec2 disc = vec2(dot(rd, e1), dot(rd, e2)) / MOON_SIZE;
    float r = length(disc);
    float edge = smoothstep(1.0, 1.0 - 2.0 * pixelAngle() / MOON_SIZE, r);
    // Full, so lit almost evenly right to its edge.
    vec3 p = vec3(disc, sqrt(max(1.0 - r * r, 0.0)));
    vec3 face = vec3(1.0, 0.97, 0.92) * moonFace(p) * (0.9 + 0.1 * p.z);
    col = mix(col, face * 0.95, edge);
  }
  vec4 cl = clouds(rd);
  return col * (1.0 - cl.a) + cl.rgb;
}
// Where a ray meets the slab, and how much of the pixel the slab covers:
// a ray that misses by less than a pixel's width still gets part of it,
// which is what smooths the silhouette. `travelled` is how far the ray had
// come already (a reflection's starts at the floor), for the width there.
vec2 marchSlab(vec3 ro, vec3 rd, float travelled) {
  float t = 0.0;
  float closest = 1e9;
  float closestT = -1.0;
  for (int i = 0; i < 80; i++) {
    float d = slab(ro + rd * t);
    if (d < 0.0008) return vec2(t, 1.0);
    float ratio = d / (pixelAngle() * (travelled + t));
    if (ratio < closest) {
      closest = ratio;
      closestT = t;
    }
    t += d;
    if (t > 14.0) break;
  }
  return vec2(closestT, 1.0 - smoothstep(0.0, 1.0, closest));
}
vec3 shadeSlab(vec3 p, vec3 rd, float dist) {
  vec3 n = slabNormal(p);
  vec3 lp = slabSpace(p);
  vec2 cuv = vec2(lp.x, -lp.y) / 1.92 + 0.5;
  // The mipmap level by hand: this runs inside a branch, where the GPU
  // cannot work it out, and the cover's lettering would sparkle.
  float texels = 512.0 * pixelAngle() * dist / 1.92 / max(abs(dot(n, rd)), 0.25);
  float lod = log2(max(texels, 1.0));
  vec3 cover = textureLod(sampler_cover, clamp(cuv, 0.0, 1.0), lod).rgb;
  vec3 mirrored = textureLod(sampler_cover, clamp(vec2(1.0 - cuv.x, cuv.y), 0.0, 1.0), lod).rgb;
  float front = smoothstep(0.02, 0.06, lp.z);
  float back = smoothstep(0.02, 0.06, -lp.z);
  vec3 edge = mix(vec3(0.02), accent() * 0.25, 0.5);
  vec3 base = edge;
  base = mix(base, cover, front);
  base = mix(base, mirrored * 0.18, back);
  vec3 light = normalize(vec3(-0.45, 0.75, 0.65));
  float diffuse = 0.62 + 0.38 * max(dot(n, light), 0.0);
  vec3 mirror = reflect(rd, n);
  float spec = pow(max(dot(mirror, light), 0.0), 48.0);
  float facing = max(dot(n, -rd), 0.0);
  float rim = pow(1.0 - facing, 3.0);
  vec3 col = base * diffuse;
  col += vec3(1.0) * spec * (0.2 + 0.25 * front);
  // A glossy print: the night mirrored in it, strongest at a slant, and
  // the moon as a sharp highlight sliding over it as it turns.
  float fresnel = 0.04 + 0.5 * pow(1.0 - facing, 5.0);
  col += sky(mirror) * fresnel * (0.4 + 0.6 * front) * 3.0;
  col += MOONLIGHT * pow(max(dot(backdrop(mirror), MOON), 0.0), 900.0) * 3.0 * (0.3 + 0.7 * front);
  // The rim catches the accent, brighter with the treble.
  col += accent() * rim * (0.5 + 1.2 * q9);
  return col;
}
const float FLOOR = -1.3;
float ripple(float r, float age) {
  float x = (r - age * 2.6) * 5.0;
  return exp(-x * x) * exp(-age * 1.5);
}
float rippleSlope(float r, float age) {
  float x = (r - age * 2.6) * 5.0;
  return -10.0 * x * exp(-x * x) * exp(-age * 1.5);
}
// The sea under the cover: a swell of waves running in many directions,
// the shorter ones quicker (as on deep water) and all of them only with
// the music, each fading out where it would be smaller than a pixel; a
// beat sends a ripple out from under the cover. It mirrors the sky - the
// moon's light breaking into a glittering path - the lighthouse's lamp
// and the cover itself.
vec3 shadeWater(vec3 p, vec3 rd, float t, vec3 lampDir, float lampPower) {
  vec2 xz = p.xz;
  float r = length(xz);
  float footprint = pixelAngle() * t / max(-rd.y, 0.04);
  vec2 g = vec2(0.0);
  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float ang = fi * 2.39996 + 0.4;
    vec2 dir = vec2(cos(ang), sin(ang));
    float k = 0.9 * pow(1.5, fi);
    float slope = 0.045 * pow(0.92, fi);
    float fade = clamp(1.5 - k * footprint * 3.0, 0.0, 1.0);
    g += dir * slope * fade * cos(dot(xz, dir) * k + q10 * 9.0 * sqrt(k / 1.2) + fi * 1.7);
  }
  float rings = ripple(r, q4) + ripple(r, q5) + ripple(r, q6);
  float ringSlope = rippleSlope(r, q4) + rippleSlope(r, q5) + rippleSlope(r, q6);
  g += 0.03 * ringSlope * xz / max(r, 0.001);
  vec3 n = normalize(vec3(-g.x, 1.0, -g.y));
  vec3 rrd = reflect(rd, n);
  rrd.y = abs(rrd.y);
  float fresnel = 0.02 + 0.98 * pow(1.0 - max(dot(n, -rd), 0.0), 5.0);
  vec3 col = vec3(0.002, 0.005, 0.009) + accent() * 0.006;
  col += sky(rrd) * fresnel;
  // The moon's path: a broader highlight than the disc alone would give,
  // as the many small facets of the swell each catch it.
  col += MOONLIGHT * pow(max(dot(backdrop(rrd), MOON), 0.0), 350.0) * 1.5 * fresnel;
  col += accent() * rings * 0.08;
  // The cover's own colour lighting the water under it, with the beat.
  col += coverAverage() * exp(-r * r * 0.9) * (0.12 + 0.25 * q8);
  float glint = pow(max(dot(rrd, lampDir), 0.0), 3000.0);
  col += mix(accent(), vec3(1.0), 0.5) * glint * lampPower * 1.6;
  // The cover in it through the long swell only: the short waves would
  // tear so near a reflection into scraps.
  vec3 calm = normalize(vec3(-g.x * 0.3, 1.0, -g.y * 0.3));
  vec3 crd = reflect(rd, calm);
  vec2 mirror = marchSlab(p + crd * 0.01, crd, t);
  if (mirror.y > 0.0) {
    vec3 seen = shadeSlab(p + crd * (0.01 + mirror.x), crd, t + mirror.x);
    col += seen * (0.2 + fresnel * 1.5) * exp(-mirror.x * 0.3) * mirror.y;
  }
  return col;
}
// The lighthouse from Beacon's logo, in the icon's own 512-unit grid (y
// down): its outline kept, but every part round, a solid of revolution
// seen a little from above, so the stripes' cuts, the gallery and the
// roof's brim show as ellipses.
float edgeOut(vec2 p, vec2 a, vec2 b, vec2 inner) {
  vec2 n = normalize(vec2(b.y - a.y, a.x - b.x));
  if (dot(inner - a, n) > 0.0) n = -n;
  return dot(p - a, n);
}
float box(vec2 p, vec2 lo, vec2 hi) {
  vec2 d = max(lo - p, p - hi);
  return max(d.x, d.y);
}
float partCover(float d, float px) {
  return clamp(0.5 - d / px, 0.0, 1.0);
}
// Where across a part between lo and hi x falls, -1 to 1, and how far the
// round surface there comes towards the viewer.
float across(float x, float lo, float hi) {
  return clamp((2.0 * x - lo - hi) / (hi - lo), -1.0, 1.0);
}
float bulge(float nx) {
  return sqrt(max(1.0 - nx * nx, 0.0));
}
// How far the lighthouse stands up out of the rock, in that grid.
const float LH_RAISE = 26.0;
const vec2 LAMP_AT = vec2(287.0, 144.0);
// In the accent, lit by the moon behind it to the right (a rim down that
// side), the sky in front, and the lamp.
vec3 shadeRound(float nx, float up, float lampLight) {
  vec3 n = normalize(vec3(nx, up, bulge(nx)));
  float moon = max(dot(n, normalize(vec3(0.6, 0.35, -0.7))), 0.0);
  float fill = max(dot(n, normalize(vec3(-0.4, 0.3, 0.85))), 0.0);
  vec3 body = accent();
  return body * (0.04 + 0.16 * fill + 0.1 * max(up, 0.0)) + MOONLIGHT * body * 0.9 * pow(moon, 1.5)
       + mix(body, vec3(1.0), 0.5) * lampLight;
}
// Its colour and how much of the pixel it covers; `lampGlow` is the lamp's
// light in the lantern's open window, to add where it shows.
vec4 lighthouse(vec2 p, float px, float lampPower, out vec3 lampGlow) {
  lampGlow = vec3(0.0);
  p.y += LH_RAISE;
  if (p.x < 200.0 || p.x > 420.0 || p.y < 30.0 || p.y > 480.0) return vec4(0.0);
  float lampD = length(p - LAMP_AT);
  lampGlow = mix(accent(), vec3(1.0), 0.5) * lampPower * (exp(-lampD * lampD / 500.0) * 1.5 + exp(-lampD / 30.0) * 0.3);
  float lampLight = lampPower * 0.35 * exp(-lampD / 30.0);
  vec4 o = vec4(0.0);
  // The tower, its two diagonal stripes cut clean through: the top of the
  // piece below each cut shows as an ellipse.
  float xl = mix(258.0, 222.0, (p.y - 216.0) / 244.0);
  float xr = 374.0 + 28.0 * (p.y - 216.0) / 204.0;
  float nx = across(p.x, xl, xr);
  float bend = 7.0 * bulge(nx);
  vec2 mid = vec2(312.0, 340.0);
  float tower = max(max(edgeOut(p, vec2(258.0, 216.0), vec2(374.0, 216.0), mid),
                        edgeOut(p, vec2(374.0, 216.0), vec2(402.0, 420.0), mid)),
                    max(max(edgeOut(p, vec2(402.0, 420.0), vec2(332.0, 460.0), mid),
                            edgeOut(p, vec2(332.0, 460.0), vec2(222.0, 460.0), mid)),
                        edgeOut(p, vec2(222.0, 460.0), vec2(258.0, 216.0), mid)));
  float u = p.y + 0.575 * p.x;
  tower = max(tower, min(u - 429.0 - bend, 470.0 - bend - u) / 1.153);
  tower = max(tower, min(u - 541.0 - bend, 580.0 - bend - u) / 1.153);
  float c = partCover(tower, px);
  if (c > 0.0) {
    float top = max(clamp((bend - abs(u - 470.0)) / px + 0.5, 0.0, 1.0),
                    clamp((bend - abs(u - 580.0)) / px + 0.5, 0.0, 1.0));
    vec3 side = shadeRound(nx, 0.0, lampLight) * (0.55 + 0.45 * smoothstep(216.0, 250.0, p.y));
    o = vec4(mix(side, shadeRound(nx * 0.4, 1.2, lampLight), top), c);
  }
  // The post beside the lantern's window.
  c = partCover(box(p, vec2(333.0, 100.0), vec2(372.0, 190.0)), px);
  if (c > 0.0) {
    o = vec4(mix(o.rgb, shadeRound(across(p.x, 333.0, 372.0), 0.0, lampLight), c), max(o.a, c));
  }
  // The gallery: a disc, its top in view.
  nx = across(p.x, 240.0, 388.0);
  bend = 5.0 * bulge(nx);
  c = partCover(box(p, vec2(240.0, 182.0 - bend), vec2(388.0, 216.0 + bend)), px);
  if (c > 0.0) {
    float top = clamp((182.0 + bend - p.y) / px + 0.5, 0.0, 1.0);
    vec3 g = mix(shadeRound(nx, 0.0, lampLight), shadeRound(nx * 0.4, 1.2, lampLight * 2.0), top);
    o = vec4(mix(o.rgb, g, c), max(o.a, c));
  }
  // The roof: a cone over a brim, as wide as the gallery.
  vec2 roofIn = vec2(314.0, 80.0);
  float roof = max(max(edgeOut(p, vec2(240.0, 88.0), vec2(315.0, 50.0), roofIn),
                       edgeOut(p, vec2(315.0, 50.0), vec2(388.0, 88.0), roofIn)),
                   box(p, vec2(240.0, 40.0), vec2(388.0, 106.0 + bend)));
  c = partCover(roof, px);
  if (c > 0.0) {
    bool cone = p.y < 88.0;
    float halfW = cone ? max(74.0 * (p.y - 50.0) / 38.0, 1.0) : 74.0;
    vec3 r = shadeRound(across(p.x, 314.0 - halfW, 314.0 + halfW), cone ? 0.8 : 0.0, lampLight);
    o = vec4(mix(o.rgb, r, c), max(o.a, c));
  }
  return o;
}
// The rock it stands on: craggy against the sky, its crest catching the
// moon, foam where the swell breaks on it, more with each beat.
float rockTop(float x) {
  float w = max(1.0 - x * x / (215.0 * 215.0), 0.0);
  // Ridged noise, for crags rather than round boulders.
  float big = 1.0 - abs(2.0 * noise3(vec3(x / 30.0, 1.3, 0.0)) - 1.0);
  float small = noise3(vec3(x / 7.0, 4.1, 0.0));
  // Up past the lighthouse's foot (LH_RAISE) everywhere under it.
  return (LH_RAISE + 6.0) * pow(w, 0.5) + 14.0 * big * w + 5.0 * small * sqrt(w);
}
vec4 rockAt(vec2 p, float px) {
  float x = p.x - 312.0;
  if (abs(x) > 215.0) return vec4(0.0);
  float h = 460.0 - p.y;
  float top = rockTop(x);
  float c = partCover(h - top, px);
  if (c <= 0.0) return vec4(0.0);
  float slope = (rockTop(x + 3.0) - rockTop(x - 3.0)) / 6.0;
  float crag = fbm(vec3(p / 14.0, 2.0), 3);
  vec3 col = vec3(0.010, 0.011, 0.014) * (0.4 + 1.2 * crag);
  // The crest, and the faces turned to the moon on its right.
  col += MOONLIGHT * exp(-(top - h) / 5.0) * (0.03 + 0.12 * clamp(-slope, 0.0, 1.0));
  col += MOONLIGHT * 0.025 * smoothstep(0.55, 0.7, crag) * smoothstep(-60.0, 120.0, x);
  float foam = smoothstep(0.5, 0.85, noise3(vec3(x / 6.0 + q10 * 4.0, h / 2.5, q10 * 3.0)))
             * exp(-h / 6.0) * (0.5 + q8);
  col += vec3(0.6, 0.65, 0.7) * foam;
  return vec4(col, c);
}
// Sea fog lying low on the water: silver towards the moon, coloured by the
// cover round it, brighter with the beat, drifting with the music. Thin
// close to the eye, so it never fogs the whole picture. Its light, and how
// much of what is behind it it hides.
const float FOG_TOP = FLOOR + 0.5;
vec4 seaFog(vec3 ro, vec3 rd, float tEnd) {
  if (rd.y >= 0.0) return vec4(0.0);
  float t0 = max((FOG_TOP - ro.y) / rd.y, 0.0);
  float t1 = min(tEnd, t0 + 16.0);
  if (t0 >= t1) return vec4(0.0);
  float dt = (t1 - t0) / 8.0;
  float t = t0 + dt * hash13(vec3(gl_FragCoord.xy, fract(q10 * 13.0) * 50.0));
  float forward = 0.35 * pow(max(dot(backdrop(rd), MOON), 0.0), 8.0);
  vec3 light = vec3(0.0);
  float through = 1.0;
  for (int i = 0; i < 8; i++) {
    vec3 p = ro + rd * t;
    float depth = clamp((FOG_TOP - p.y) / (FOG_TOP - FLOOR), 0.0, 1.0);
    float wisp = fbm(vec3(p.xz * vec2(0.55, 0.9) + vec2(q10 * 1.4, q10 * 0.5), p.y * 1.5 + q10 * 0.4), 3);
    float dens = smoothstep(0.0, 0.8, depth) * smoothstep(0.48, 0.75, wisp) * smoothstep(1.5, 4.0, t) * smoothstep(18.0, 9.0, t) * 2.5;
    vec3 lit = MOONLIGHT * (0.07 + forward) + accent() * 0.03
             + coverAverage() * exp(-dot(p.xz, p.xz) * 0.35) * (0.3 + 0.6 * q8);
    float a = 1.0 - exp(-dens * dt);
    light += lit * a * through;
    through *= 1.0 - a;
    t += dt;
  }
  return vec4(light, 1.0 - through);
}
// Fireflies over the water in the cover's colour, more of them the louder
// it plays. Each glows and goes dark again in its own time, some flicker,
// and a beat lights them all up at once, the dark ones briefly too. They
// sit on upright sheets one behind the
// other, so they pass the cover and each other as the camera swings; the
// nearest out of focus. None inside the cover's reach, where it would cut
// one in half, and they fade out before they come too close to the eye.
vec3 motes(vec3 ro, vec3 rd, float tEnd) {
  vec3 tint = mix(coverAverage(), accent(), 0.3) * 2.2 + 0.05;
  float share = 0.03 + 0.05 * q12;
  vec3 sum = vec3(0.0);
  for (int l = 0; l < 7; l++) {
    float t = (4.4 - float(l) * 1.1 - ro.z) / rd.z;
    if (t < 0.3 || t > tEnd) continue;
    vec3 p = ro + rd * t;
    if (p.y < FLOOR) continue;
    vec2 q = vec2(p.x, p.y - q10 * 0.3) / 0.45;
    float size = max(0.01, pixelAngle() * t * 1.2) + 0.025 * smoothstep(2.5, 1.0, t);
    // Each mote's halo reaches into the cells around it.
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 cell = floor(q) + vec2(float(i), float(j));
        float h = hash13(vec3(cell, float(l)));
        vec2 at = cell + 0.25 + 0.5 * vec2(hash13(vec3(cell, float(l) + 9.0)), hash13(vec3(cell, float(l) + 4.0)));
        // Wandering, never far from home.
        at += 0.22 * vec2(sin(q13 * 0.37 + h * 40.0) + 0.5 * sin(q13 * 0.91 + h * 13.0),
                          cos(q13 * 0.29 + h * 70.0) + 0.5 * cos(q13 * 0.83 + h * 23.0));
        vec3 world = vec3(at.x * 0.45, at.y * 0.45 + q10 * 0.3, p.z);
        if (h > share * smoothstep(1.4, -0.6, world.y)) continue;
        if (length(world - vec3(0.0, 0.05, 0.0)) < 1.5) continue;
        float d = length(q - at) * 0.45;
        float k = hash13(vec3(cell, float(l) + 17.0));
        float phase = fract(q13 / (2.5 + 4.0 * k) + h * 37.0);
        float lit = smoothstep(0.0, 0.12, phase) * smoothstep(0.5, 0.3, phase);
        float flicker = 0.55 + 0.45 * sin(q13 * 23.0 + h * 90.0) * sin(q13 * 7.3 + k * 60.0);
        lit *= mix(1.0, flicker, step(0.7, k));
        float pulse = exp(-q4 * 5.0);
        float twinkle = max(lit, pulse * 0.7) * (1.0 + 1.2 * pulse) * (0.85 + 0.3 * q9);
        // A bright core in a wide soft halo.
        float glow = exp(-d * d / (size * size)) + 0.25 * exp(-d * d / (16.0 * size * size));
        sum += tint * glow * pow(0.01 / size, 1.5) * twinkle * 1.6 * smoothstep(0.9, 1.8, t);
      }
    }
  }
  return sum;
}
 shader_body {
  vec2 s = (uv_orig - 0.5) / aspect.yx;
  s.y = -s.y;
  float swing = camAngle();
  vec3 ro = vec3(6.2 * sin(swing), 0.55 + 0.25 * sin(q7 * 0.7), 6.2 * cos(swing));
  vec3 target = vec3(0.0, -0.08, 0.0);
  vec3 fwd = normalize(target - ro);
  vec3 right = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, fwd);
  vec3 rd = normalize(fwd * 1.75 + right * s.x + up * s.y);
  // Behind everything: a dark haze in the accent, lit by the cover.
  // The lighthouse from Beacon's logo stands on a rock on the horizon,
  // beside the cover, mirrored in the sea. It swings with the rest of the
  // far scene (FAR_SWING), level with the horizon. Its beam turns
  // with the music and flares when it sweeps past the viewer. Heights
  // here are in s.y / 1.75: a direction's up over its forward part.
  vec3 level = normalize(vec3(fwd.x, 0.0, fwd.z));
  float horizon = dot(level, up) / dot(level, fwd);
  float halfWidth = 0.5 / aspect.y / 1.75;
  float lhX = -0.58 * halfWidth;
  float lhScale = 410.0 / 0.13;
  float px = pixelAngle() * lhScale;
  float sx = s.x / 1.75 - FAR_SWING * swing;
  float el = s.y / 1.75;
  vec2 lamp = vec2(lhX + (LAMP_AT.x - 312.0) / lhScale, horizon + (460.0 - LAMP_AT.y + LH_RAISE) / lhScale);
  vec3 lampDir = normalize(fwd + right * (lamp.x + FAR_SWING * swing) + up * lamp.y);
  float sweep = sin(q11);
  float facing = cos(q11);
  float lampPower = 0.25 + 0.6 * pow(max(facing, 0.0), 2.0) + 0.5 * q8;

  vec3 col = sky(rd);
  col += coverAverage() * 0.12 * exp(-dot(s, s) * 2.5);
  // Stars, fixed to the sky so they turn with the camera: a few bright
  // ones and many faint, fewer near the moon's glare and hidden by the
  // clouds; they twinkle with the treble.
  vec3 far = backdrop(rd);
  if (far.y > 0.0) {
    vec3 starsCol = vec3(0.0);
    for (int l = 0; l < 3; l++) {
      float scale = 70.0 * pow(2.0, float(l));
      vec3 cell = floor(far * scale);
      float h = hash13(cell + float(l) * 17.0);
      if (h > 0.22) continue;
      vec3 at = normalize(cell + 0.2 + 0.6 * vec3(hash13(cell + 3.1), hash13(cell + 5.7), hash13(cell + 8.3)));
      float d = length(cross(far, at)) / (pixelAngle() * 1.1);
      float lum = pow(0.45, float(l)) * (0.2 + 1.6 * pow(h / 0.22, 4.0));
      float twinkle = 0.7 + 0.3 * sin(h * 400.0 + q10 * 12.0) * (0.4 + q9);
      starsCol += mix(vec3(1.0), mix(vec3(1.0, 0.85, 0.7), vec3(0.75, 0.85, 1.0), hash13(cell + 11.0)), 0.5) * lum * twinkle * exp(-d * d);
    }
    float glare = smoothstep(0.92, 0.995, dot(far, MOON));
    col += starsCol * (1.0 - glare) * (1.0 - clouds(far).a) * smoothstep(0.0, 0.08, far.y);
  }
  float tFloor = rd.y < 0.0 ? (FLOOR - ro.y) / rd.y : 1e9;
  if (tFloor < 1e8) {
    // Into the haze with the distance, so the sea meets the sky softly.
    vec3 water = shadeWater(ro + rd * tFloor, rd, tFloor, lampDir, lampPower);
    col = mix(col, water, exp(-tFloor * 0.035));
  }
  // Above the horizon the lighthouse, below it the same mirrored, faint
  // and broken up by the swell.
  bool above = el > horizon;
  float mirrorEl = above ? el : 2.0 * horizon - el;
  float waver = above ? 0.0 : 0.0015 * min(1.0, (horizon - el) * 20.0) * sin(el * 900.0 + q10 * 9.0);
  float seen = above ? 1.0 : 0.3 * exp((el - horizon) * 25.0);
  vec2 lp = vec2(312.0 + (sx + waver - lhX) * lhScale, 460.0 - (mirrorEl - horizon) * lhScale);
  vec3 lampGlow;
  vec4 tower = lighthouse(lp, px, lampPower, lampGlow);
  col += lampGlow * seen;
  col = mix(col, tower.rgb, tower.a * seen);
  vec4 rk = rockAt(lp, px);
  col = mix(col, rk.rgb, rk.a * seen);
  vec2 fromLamp = vec2(sx + waver, mirrorEl) - lamp;
  float along = fromLamp.x * sign(sweep);
  float reach = 0.04 + 0.9 * abs(sweep);
  float spread = 0.0035 + max(along, 0.0) * 0.16;
  float beam = smoothstep(spread, spread * 0.25, abs(fromLamp.y)) * smoothstep(0.0, 0.004, along)
             * smoothstep(reach, 0.0, along);
  // Haze drifting through it, moved on by the music.
  beam *= 0.85 + 0.15 * sin(along * 22.0 - q10 * 4.0);
  beam *= 0.3 + 0.7 * max(facing, 0.0);
  float r2 = dot(fromLamp, fromLamp);
  float glare = exp(-r2 * 9000.0) * (0.5 + 0.8 * q8) + exp(-r2 * 600.0) * pow(max(facing, 0.0), 6.0) * 0.6;
  col += mix(accent(), vec3(1.0), 0.35) * (beam * 0.55 + glare) * seen;
  // The cover over whatever is behind it, by how much of the pixel it covers.
  vec2 hit = marchSlab(ro, rd, 0.0);
  float tEnd = tFloor;
  if (hit.y > 0.0 && hit.x < tFloor) {
    col = mix(col, shadeSlab(ro + rd * hit.x, rd, hit.x), hit.y);
    tEnd = hit.x;
  }
  vec4 fog = seaFog(ro, rd, tEnd);
  col = col * (1.0 - fog.a) + fog.rgb;
  col += motes(ro, rd, tEnd);
  ret = col;
 }

preset.comp:
shader_body {
 vec3 col = texture(sampler_main, uv).rgb;
 // A glow of its own from this frame's picture: Butterchurn's blur
 // textures sit offset from it and doubled every edge. Only what is
 // bright glows.
 vec3 glow = vec3(0.0);
 // Turned per pixel by noise, so the taps blur into one another instead
 // of standing out as rings.
 // Interleaved gradient noise: even, and fine enough to vanish in the blur.
 float spin = 6.2832 * fract(52.9829 * fract(dot(uv * texsize.xy, vec2(0.06711, 0.00584))));
 for (int i = 0; i < 24; i++) {
   float a = float(i) * 2.39996 + spin;
   float r = 0.02 * sqrt((float(i) + 0.5) / 24.0);
   vec2 o = vec2(cos(a), sin(a)) * r * vec2(aspect.y, 1.0);
   glow += max(texture(sampler_main, uv + o).rgb - 0.35, 0.0);
 }
 col += glow / 24.0 * 1.6;
 col = 1.0 - exp(-col * 1.35);
 col *= 1.0 - 0.5 * pow(clamp(rad * 1.25, 0.0, 1.0), 2.5);
 ret = col;
}
